using System.ComponentModel.DataAnnotations;

namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }

    [Required, StringLength(200)]
    public string Title { get; set; } = string.Empty;

    public string Category { get; set; } = string.Empty;

    [Required, MinLength(1)]
    public List<string> Ingredients { get; set; } = [];

    [Required, MinLength(1)]
    public List<string> Steps { get; set; } = [];

    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeCategory
{
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string Icon { get; set; } = string.Empty;
    public int RecipeCount { get; set; }
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil"],
            Steps = ["Preheat oven to 475°F.", "Roll out dough on floured surface.", "Spread crushed tomatoes evenly.", "Add torn mozzarella pieces.", "Bake 10-12 minutes until crust is golden.", "Top with fresh basil and drizzle olive oil."],
            AverageRating = 4.5, RatingCount = 12
        },
        new()
        {
            Id = 2, Title = "Chicken Tikka Masala", Category = "Indian",
            Ingredients = ["Chicken thighs", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Garlic", "Ginger"],
            Steps = ["Marinate chicken in yogurt and spices for 2 hours.", "Grill or broil chicken until charred.", "Sauté garlic and ginger in oil.", "Add tomato sauce and simmer 15 minutes.", "Stir in cream and cooked chicken.", "Simmer 10 more minutes and serve with rice."],
            AverageRating = 4.8, RatingCount = 24
        },
        new()
        {
            Id = 3, Title = "Beef Tacos", Category = "Mexican",
            Ingredients = ["Ground beef", "Taco seasoning", "Corn tortillas", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream"],
            Steps = ["Brown ground beef in a skillet.", "Add taco seasoning and water, simmer 5 minutes.", "Warm tortillas in a dry pan.", "Assemble tacos with beef and toppings.", "Serve with lime wedges."],
            AverageRating = 4.2, RatingCount = 8
        },
        new()
        {
            Id = 4, Title = "Pad Thai", Category = "Asian",
            Ingredients = ["Rice noodles", "Shrimp", "Eggs", "Bean sprouts", "Peanuts", "Tamarind paste", "Fish sauce", "Lime"],
            Steps = ["Soak rice noodles in warm water 30 minutes.", "Stir-fry shrimp until pink, set aside.", "Scramble eggs in the wok.", "Add drained noodles, tamarind paste, fish sauce, and sugar.", "Toss with shrimp, bean sprouts, and peanuts.", "Serve with lime wedges and chili flakes."],
            AverageRating = 4.6, RatingCount = 15
        },
        new()
        {
            Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts",
            Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
            Steps = ["Preheat oven to 425°F and grease ramekins.", "Melt chocolate and butter together.", "Whisk eggs, sugar, and vanilla until thick.", "Fold chocolate mixture into eggs, then fold in flour.", "Pour into ramekins and bake 12-14 minutes.", "Invert onto plates and serve immediately."],
            AverageRating = 4.9, RatingCount = 30
        },
        new()
        {
            Id = 6, Title = "Caesar Salad", Category = "Salads",
            Ingredients = ["Romaine lettuce", "Parmesan cheese", "Croutons", "Anchovy paste", "Garlic", "Lemon juice", "Olive oil", "Egg yolk"],
            Steps = ["Whisk anchovy paste, garlic, lemon juice, and egg yolk.", "Slowly drizzle in olive oil while whisking to emulsify.", "Tear romaine into bite-sized pieces.", "Toss lettuce with dressing.", "Top with shaved Parmesan and croutons."],
            AverageRating = 4.0, RatingCount = 6
        }
    ];

    private readonly List<RecipeCategory> _categories =
    [
        new() { Name = "Italian", Description = "Pasta, pizza, and Mediterranean flavors", Icon = "🍝", RecipeCount = 1 },
        new() { Name = "Indian", Description = "Bold spices and rich curries", Icon = "🍛", RecipeCount = 1 },
        new() { Name = "Mexican", Description = "Tacos, burritos, and vibrant salsas", Icon = "🌮", RecipeCount = 1 },
        new() { Name = "Asian", Description = "Stir-fries, noodles, and umami flavors", Icon = "🍜", RecipeCount = 1 },
        new() { Name = "Desserts", Description = "Sweet treats and baked goods", Icon = "🍰", RecipeCount = 1 },
        new() { Name = "Salads", Description = "Fresh and healthy greens", Icon = "🥗", RecipeCount = 1 }
    ];

    public List<RecipeCategory> GetCategories() => _categories;

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);

        var category = _categories.FirstOrDefault(c => c.Name.Equals(recipe.Category, StringComparison.OrdinalIgnoreCase));
        if (category != null)
            category.RecipeCount++;
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount;
        recipe.RatingCount++;
        recipe.AverageRating = Math.Round((totalStars + stars) / recipe.RatingCount, 1);
    }
}

