            Ingredients = ["Romaine lettuce", "Parmesan cheese", "Croutons", "Anchovy paste", "Garlic", "Lemon juice", "Olive oil", "Egg yolk"],
            Steps = ["Whisk anchovy paste, garlic, lemon juice, and egg yolk.", "Slowly drizzle in olive oil while whisking to emulsify.", "Tear romaine into bite-sized pieces.", "Toss lettuce with dressing.", "Top with shaved Parmesan and croutons."],
            AverageRating = 4.0, RatingCount = 6
        }
    ];

    private readonly List<RecipeCategory> _categories =
    [
        new() { Name = "Italian", Description = "Pasta, pizza, and Mediterranean flavors", Icon = "🍝", RecipeCount = 1 },
        new() { Name = "Indian", Description = "Bold spices and rich curries", Icon = "🍛", RecipeCount = 1 },
        new() { Name = "Mexican", Description = "Tacos, burritos, and vibrant salsas", Icon = "🌮", RecipeCount = 1 },
        new() { Name = "Asian", Description = "Stir-fries, noodles, and umami flavors", Icon = "🍜", RecipeCount = 1 },
        new() { Name = "Desserts", Description = "Sweet treats and baked goods", Icon = "🍰", RecipeCount = 1 },
        new() { Name = "Salads", Description = "Fresh and healthy greens", Icon = "🥗", RecipeCount = 1 }
    ];

    public List<RecipeCategory> GetCategories() => _categories;

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);

        var category = _categories.FirstOrDefault(c => c.Name.Equals(recipe.Category, StringComparison.OrdinalIgnoreCase));
        if (category != null)
            category.RecipeCount++;
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount;
        recipe.RatingCount++;
        recipe.AverageRating = Math.Round((totalStars + stars) / recipe.RatingCount, 1);
    }
}

