@page "/category/{CategoryName}"
@using RecipeShare.Services
@using RecipeShare.Models
@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes - RecipeShare</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">@CategoryName</li>
        </ol>
    </nav>

    <h1>@CategoryName Recipes</h1>

    @if (recipes.Count == 0)
    {
        <p class="text-muted">No recipes found in this category yet.</p>
    }
    else
    {
        <div class="list-group mt-3">
            @foreach (var recipe in recipes)
            {
                <a href="/recipe/@recipe.Id" class="list-group-item list-group-item-action">
                    <div class="d-flex w-100 justify-content-between">
                        <h5 class="mb-1">@recipe.Title</h5>
                        <small>⭐ @recipe.AverageRating (@recipe.RatingCount ratings)</small>
                    </div>
                    <p class="mb-1 text-muted">@recipe.Ingredients.Count ingredients · @recipe.Steps.Count steps</p>
                </a>
            }
        </div>
    }
</div>

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;

    private List<Recipe> recipes = [];

    protected override void OnParametersSet()
    {
        recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@using RecipeShare.Services
@using RecipeShare.Models
@inject RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe") - RecipeShare</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            @if (recipe is not null)
            {
                <li class="breadcrumb-item"><a href="/category/@recipe.Category">@recipe.Category</a></li>
                <li class="breadcrumb-item active">@recipe.Title</li>
            }
        </ol>
    </nav>

    @if (recipe is null)
    {
        <p class="text-danger">Recipe not found.</p>
    }
    else
    {
        <h1>@recipe.Title</h1>
        <p class="text-muted">Category: @recipe.Category · ⭐ @recipe.AverageRating (@recipe.RatingCount ratings)</p>

        <StarRating RecipeId="recipe.Id" @rendermode="Microsoft.AspNetCore.Components.Web.RenderMode.InteractiveServer" />

        <h3 class="mt-4">Ingredients</h3>
        <ul class="list-group list-group-flush mb-4">
            @foreach (var ingredient in recipe.Ingredients)
            {
                <li class="list-group-item">@ingredient</li>
            }
        </ul>

        <h3>Steps</h3>
        <ol class="list-group list-group-numbered mb-4">
            @foreach (var step in recipe.Steps)
            {
                <li class="list-group-item">@step</li>
            }
        </ol>
    }
</div>

@code {
    [Parameter] public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetRecipeById(Id);
    }
}

@using RecipeShare.Services
@inject RecipeService RecipeService
@rendermode InteractiveServer

<div class="my-3 p-3 border rounded">
    <h5>Rate this recipe</h5>
    <div class="d-flex align-items-center gap-1">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <button class="btn btn-link p-0 fs-3 text-decoration-none"
                    @onclick="() => SubmitRating(star)"
                    title="Rate @star stars">
                @(star <= selectedRating ? "★" : "☆")
            </button>
        }
        @if (submitted)
        {
            <span class="ms-3 text-success">✓ Thanks for rating!</span>
        }
    </div>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }

    private int selectedRating;
    private bool submitted;

    private void SubmitRating(int stars)
    {
        selectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        submitted = true;
    }
}

@page "/submit"
@using RecipeShare.Services
@using RecipeShare.Models
@rendermode InteractiveServer
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">Submit Recipe</li>
        </ol>
    </nav>

    <h1>📝 Submit a Recipe</h1>
    <p class="text-muted">Share your favorite recipe with the community!</p>

    <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="submit-recipe" class="mt-3">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" @bind-Value="model.Title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
            <ValidationMessage For="() => model.Title" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" @bind-Value="model.Category" class="form-select">
                <option value="">-- Select a category --</option>
                <option value="Italian">Italian</option>
                <option value="Indian">Indian</option>
                <option value="Mexican">Mexican</option>
                <option value="Asian">Asian</option>
                <option value="Desserts">Desserts</option>
                <option value="Salads">Salads</option>
            </InputSelect>
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" @bind-Value="ingredientsText" class="form-control" rows="5"
                           placeholder="1 cup flour&#10;2 eggs&#10;1/2 cup sugar" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps (one per line)</label>
            <InputTextArea id="steps" @bind-Value="stepsText" class="form-control" rows="5"
                           placeholder="Preheat oven to 350°F.&#10;Mix dry ingredients.&#10;Add wet ingredients." />
        </div>

        <button type="submit" class="btn btn-success">Submit Recipe</button>
    </EditForm>
</div>

@code {
    private RecipeFormModel model = new();
    private string ingredientsText = string.Empty;
    private string stepsText = string.Empty;

    private void HandleSubmit()
    {
        var recipe = new Recipe
        {
            Title = model.Title,
            Category = model.Category,
            Ingredients = ingredientsText.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = stepsText.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList()
        };

        RecipeService.AddRecipe(recipe);
        Navigation.NavigateTo($"/category/{recipe.Category}");
    }

    private class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Title is required")]
        [System.ComponentModel.DataAnnotations.StringLength(200)]
        public string Title { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Category is required")]
        public string Category { get; set; } = string.Empty;
    }
}

